CREATE TABLE IF NOT EXISTS booking_tracking_sessions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), booking_id uuid NOT NULL REFERENCES bookings(id), provider_id uuid NOT NULL REFERENCES provider_profiles(user_id), status text NOT NULL CHECK(status IN ('ACTIVE','STOPPED')), started_at timestamptz NOT NULL DEFAULT now(), stopped_at timestamptz);
CREATE TABLE IF NOT EXISTS booking_locations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), booking_id uuid NOT NULL REFERENCES bookings(id) ON DELETE CASCADE, provider_id uuid NOT NULL REFERENCES provider_profiles(user_id), latitude numeric(9,6) NOT NULL, longitude numeric(9,6) NOT NULL, accuracy_meters numeric(8,2), captured_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS safety_incidents (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), booking_id uuid NOT NULL REFERENCES bookings(id), reporter_id uuid NOT NULL REFERENCES users(id), severity text NOT NULL CHECK(severity IN ('LOW','MEDIUM','HIGH','EMERGENCY')), status text NOT NULL CHECK(status IN ('OPEN','ACKNOWLEDGED','RESOLVED')), description text NOT NULL, location_id uuid REFERENCES booking_locations(id), created_at timestamptz NOT NULL DEFAULT now(), resolved_at timestamptz);
CREATE INDEX IF NOT EXISTS booking_locations_booking_idx ON booking_locations(booking_id, captured_at DESC);
CREATE INDEX IF NOT EXISTS safety_incidents_status_idx ON safety_incidents(status, created_at DESC);
